INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1872324, 258014, 15711, '<td valign="top">ROFL  This would make a great off the wall greeting card.  NOt the best image but it did make me chuckle. For that - a 7</td>', 'ROFL  This would make a great off the wall greeting card.  NOt the best image but it did make me chuckle. For that - a 7', '2005-11-16 09:44:46.000000', NULL, 1),
(1872329, 256311, 45857, '<td valign="top">Doe Eyes  Great shot.</td>', 'Doe Eyes  Great shot.', '2005-11-16 09:45:31.000000', NULL, 1),
(1872331, 257302, 15711, '<td valign="top">She sure did.  Wow - if this isn''t camo, nothing is. I wonder what adjusting curves would do to enrich it just a touch?? Nice DOF.</td>', 'She sure did.  Wow - if this isn''t camo, nothing is. I wonder what adjusting curves would do to enrich it just a touch?? Nice DOF.', '2005-11-16 09:45:51.000000', NULL, 1),
(1872334, 256781, 15711, '<td valign="top">HEE HEE - I like that you have to study the image to get it.  That is true camouflage.  Very well done.  Great graphic sense to it.  The leading line and light is spot on! 9</td>', 'HEE HEE - I like that you have to study the image to get it.  That is true camouflage.  Very well done.  Great graphic sense to it.  The leading line and light is spot on! 9', '2005-11-16 09:46:45.000000', NULL, 1),
(1872340, 258160, 45857, '<td valign="top">Uh Huh, I see the lurking nail back there. Clever idea</td>', 'Uh Huh, I see the lurking nail back there. Clever idea', '2005-11-16 09:47:38.000000', NULL, 1),
(1872362, 258029, 45857, '<td valign="top">Blue blouse, blue skirt, blue sky. Good perspective. I even see the concept behind the title. What I don''t see is how this shows camouflage. What''s being concealed?</td>', 'Blue blouse, blue skirt, blue sky. Good perspective. I even see the concept behind the title. What I don''t see is how this shows camouflage. What''s being concealed?', '2005-11-16 09:51:39.000000', NULL, 1),
(1872365, 258246, 46723, '<td valign="top">Very very great picture ! I loved this.. 9 !</td>', 'Very very great picture ! I loved this.. 9 !', '2005-11-16 09:52:19.000000', NULL, 1),
(1872370, 256329, 12448, '<td valign="top">Oh, there he is!  Nice shot!  The way he blends in fits very well into the challenge.  I like the idea/concept of the shot but the over all composition leaves me a bit wanting.  It''s very centered and everything but the dark line between the first row of bushes and the second one keeps competing and drawing me away.  Also the colors seem a bit flat and dull overall.  The lighting is nice for the shot, maybe just a slight adjustment to the color balance or saturation to bring out the colors more?  As is a 6</td>', 'Oh, there he is!  Nice shot!  The way he blends in fits very well into the challenge.  I like the idea/concept of the shot but the over all composition leaves me a bit wanting.  It''s very centered and everything but the dark line between the first row of bushes and the second one keeps competing and drawing me away.  Also the colors seem a bit flat and dull overall.  The lighting is nice for the shot, maybe just a slight adjustment to the color balance or saturation to bring out the colors more?  As is a 6', '2005-11-16 09:53:35.000000', NULL, 1),
(1872372, 258077, 46723, '<td valign="top">This picture is perfect.. Remind me ... DAVID !<br/>Very very very very very very very nice !!!<br/>Loved this.<br/>Great job, i''ve never seen anything more beautiful.<br/>Keep doing nice works, your pictures are wonderful.</td>', 'This picture is perfect.. Remind me ... DAVID !Very very very very very very very nice !!!Loved this.Great job, i''ve never seen anything more beautiful.Keep doing nice works, your pictures are wonderful.', '2005-11-16 09:53:49.000000', NULL, 1),
(1872380, 257641, 15711, '<td valign="top">Love the title.  He certainly is hidden, using the sepia filter!!</td>', 'Love the title.  He certainly is hidden, using the sepia filter!!', '2005-11-16 09:54:30.000000', NULL, 1),
(1872381, 257759, 45857, '<td valign="top">Beautiful photo of a handsome bird. Technically amazing. But the concept of camouflage is a bit weak against the green background.</td>', 'Beautiful photo of a handsome bird. Technically amazing. But the concept of camouflage is a bit weak against the green background.', '2005-11-16 09:55:01.000000', NULL, 1),
(1872384, 256888, 12448, '<td valign="top">talk about your camouflage!  I can''t see them at all!  This is a very nice shot and has great potential.  The lighting and the colors are wonderful overall but it''s lacking that final POW factor that would push it over the top.  I''m a new convert to the glow technique using the gaussian blur filter to give a shot that fantasy look.  I think this shot would really benifit from that treatment, especially with the title you are attaching to it.  As is a 6</td>', 'talk about your camouflage!  I can''t see them at all!  This is a very nice shot and has great potential.  The lighting and the colors are wonderful overall but it''s lacking that final POW factor that would push it over the top.  I''m a new convert to the glow technique using the gaussian blur filter to give a shot that fantasy look.  I think this shot would really benifit from that treatment, especially with the title you are attaching to it.  As is a 6', '2005-11-16 09:55:22.000000', NULL, 1),
(1872386, 257203, 15711, '<td valign="top">I don''t like the wrinkled curtain effect, but that is a wonderful pet portrait.  Not really seeing camouflage, but the focus and the kitty give it a 7</td>', 'I don''t like the wrinkled curtain effect, but that is a wonderful pet portrait.  Not really seeing camouflage, but the focus and the kitty give it a 7', '2005-11-16 09:55:39.000000', NULL, 1),
(1872391, 258109, 15711, '<td valign="top">You clever one.  I had to really study this, which I like.  That''s camouflage - the ol'' paper bag.  GOOD ONE.  NOt the most interesting, but certainly works.  I like that hint of purple too.</td>', 'You clever one.  I had to really study this, which I like.  That''s camouflage - the ol'' paper bag.  GOOD ONE.  NOt the most interesting, but certainly works.  I like that hint of purple too.', '2005-11-16 09:56:20.000000', NULL, 1),
(1872392, 258083, 15711, '<td valign="top">Reminds me of that scene in "E.T"  HEE HEE - not a hug fan of stuffed animal shots, but ya gotta say this is pretty darn cute!!</td>', 'Reminds me of that scene in "E.T"  HEE HEE - not a hug fan of stuffed animal shots, but ya gotta say this is pretty darn cute!!', '2005-11-16 09:56:57.000000', NULL, 1),
(1872394, 257583, 15711, '<td valign="top">Now somebody went to some trouble for this one.  I thought it WAS the Statue of Liberty in the thumbnail.  CLEVER.  NOt really camouflage, but imposter for sure.</td>', 'Now somebody went to some trouble for this one.  I thought it WAS the Statue of Liberty in the thumbnail.  CLEVER.  NOt really camouflage, but imposter for sure.', '2005-11-16 09:57:39.000000', NULL, 1),
(1872395, 257745, 12448, '<td valign="top">Wow, remind me never to you get mad at me, LOL!<br/> <br/>Nice shot (no pun intended) and good concept on the idea.  But do SWAT people wear camouflage?  I always seem to remember them in all black for some reason unless of course you''re in the military then you wear the camouflage. <br/> <br/>Anyhoo, back to the picture, I like the way the barrel of the firearm brings you into the shot, taking you to the person behind the firearm.  The DOF is okay on this bt I don''t really see anyone part that is really super sharp compared to the rest.  The sight would have been the perfect part, to me, to have in focus.  The lighting is well done and the colors work very well also.  A 7</td>', 'Wow, remind me never to you get mad at me, LOL! Nice shot (no pun intended) and good concept on the idea.  But do SWAT people wear camouflage?  I always seem to remember them in all black for some reason unless of course you''re in the military then you wear the camouflage.  Anyhoo, back to the picture, I like the way the barrel of the firearm brings you into the shot, taking you to the person behind the firearm.  The DOF is okay on this bt I don''t really see anyone part that is really super sharp compared to the rest.  The sight would have been the perfect part, to me, to have in focus.  The lighting is well done and the colors work very well also.  A 7', '2005-11-16 09:57:52.000000', NULL, 1),
(1872397, 258169, 45857, '<td valign="top">Camouflage is a bit of a strecth, but cute kitten.<br/>He''s got big furry feet like my golden and other hobbits.  Love it.</td>', 'Camouflage is a bit of a strecth, but cute kitten.He''s got big furry feet like my golden and other hobbits.  Love it.', '2005-11-16 09:58:45.000000', NULL, 1),
(1872400, 256894, 45857, '<td valign="top">Very good how her bandana hat blends with the apples.</td>', 'Very good how her bandana hat blends with the apples.', '2005-11-16 10:00:17.000000', NULL, 1),
(1872402, 256894, 12448, '<td valign="top">OMG, is she standing in that tree?  WOW!  That is a brave Apple Lady!  LOL :)<br/> <br/>She does almost blend in despite the colors of her clothes and normally I would say this image looks really flat and dull for the colors but in this case it works out wonderfully for the challenge and the purpose of the photo.  <br/> <br/>I like the overall shot but the centering of the apple lady seems off to me, the whole left side of the picture really serves no purpose in my mind and you could crop it tighter on that side, bringing the edge up to the basket, leaving her with the larger amount of apples on the right.  The light does seem a bit dull and to me, could be brought up just a touch, very little but just a tiny touch.  As is a 7</td>', 'OMG, is she standing in that tree?  WOW!  That is a brave Apple Lady!  LOL :) She does almost blend in despite the colors of her clothes and normally I would say this image looks really flat and dull for the colors but in this case it works out wonderfully for the challenge and the purpose of the photo.   I like the overall shot but the centering of the apple lady seems off to me, the whole left side of the picture really serves no purpose in my mind and you could crop it tighter on that side, bringing the edge up to the basket, leaving her with the larger amount of apples on the right.  The light does seem a bit dull and to me, could be brought up just a touch, very little but just a tiny touch.  As is a 7', '2005-11-16 10:02:01.000000', NULL, 1),
(1872407, 257740, 15711, '<td valign="top">I think I kinda like this one.  A tongue in cheek approach almost.</td>', 'I think I kinda like this one.  A tongue in cheek approach almost.', '2005-11-16 10:02:52.000000', NULL, 1),
(1872409, 256738, 32754, '<td valign="top">wow, this is great...what a camouflaged butterfly!  Well done..good dof and position on orange works really well.</td>', 'wow, this is great...what a camouflaged butterfly!  Well done..good dof and position on orange works really well.', '2005-11-16 10:03:08.000000', NULL, 1),
(1872411, 258124, 15711, '<td valign="top">HEE HEE!  YOU PAINTED AN APPLE. That shows ingenuity. You get an A for effort on that one.</td>', 'HEE HEE!  YOU PAINTED AN APPLE. That shows ingenuity. You get an A for effort on that one.', '2005-11-16 10:03:53.000000', NULL, 1),
(1872413, 256888, 15711, '<td valign="top">..... or gnomes. hee hee</td>', '..... or gnomes. hee hee', '2005-11-16 10:04:08.000000', NULL, 1),
(1872421, 258245, 15711, '<td valign="top">OH WOW - I had to study that and isn''t that what camo is all about????? THis is very artful. I see it in a nouveau gallery. CLEVER. The light on the face is a tad hot though.  Otherwise, A for effort!!!</td>', 'OH WOW - I had to study that and isn''t that what camo is all about????? THis is very artful. I see it in a nouveau gallery. CLEVER. The light on the face is a tad hot though.  Otherwise, A for effort!!!', '2005-11-16 10:05:38.000000', NULL, 1),
(1872423, 256819, 15711, '<td valign="top">Boy, he sure is.  You hardly see him. Not overly interesting, but considering the challenge criteria, it suits it well. 7</td>', 'Boy, he sure is.  You hardly see him. Not overly interesting, but considering the challenge criteria, it suits it well. 7', '2005-11-16 10:06:09.000000', NULL, 1),
(1872425, 257567, 15711, '<td valign="top">HEE HEE - funny.  I think I''d adjust curves to really give the green some punch. CUte idea though. 7</td>', 'HEE HEE - funny.  I think I''d adjust curves to really give the green some punch. CUte idea though. 7', '2005-11-16 10:06:36.000000', NULL, 1),
