(1875945, 257814, 42984, '<td valign="top">What a great camouflage idea :)</td>', 'What a great camouflage idea :)', '2005-11-17 01:57:25.000000', NULL, 1),
(1875946, 257478, 42984, '<td valign="top">Terrificly haunting image, I''m sorry I haev to mark it down for not really being what I can see as a camouflage image</td>', 'Terrificly haunting image, I''m sorry I haev to mark it down for not really being what I can see as a camouflage image', '2005-11-17 01:59:33.000000', NULL, 1),
