(1875953, 256671, 42984, '<td valign="top">Attractive image but just doesn''t feel camouflahed</td>', 'Attractive image but just doesn''t feel camouflahed', '2005-11-17 02:04:01.000000', NULL, 1),
(1875956, 256354, 42984, '<td valign="top">Great image!  Meets the challenge, has great composition, is sharp and has a wow factor ... top 10 I tnk</td>', 'Great image!  Meets the challenge, has great composition, is sharp and has a wow factor ... top 10 I tnk', '2005-11-17 02:05:17.000000', NULL, 1),
(1875960, 258262, 42984, '<td valign="top">Interesting image and I like the composition but i just seems a little dull</td>', 'Interesting image and I like the composition but i just seems a little dull', '2005-11-17 02:06:28.000000', NULL, 1),
(1875963, 258234, 42984, '<td valign="top">Great stuff, perfect challenge, well lit and composed</td>', 'Great stuff, perfect challenge, well lit and composed', '2005-11-17 02:07:48.000000', NULL, 1),
(1875965, 258095, 42984, '<td valign="top">Well done, but just not original as this got a ''Transparency" ribbob last week.</td>', 'Well done, but just not original as this got a ''Transparency" ribbob last week.', '2005-11-17 02:09:10.000000', NULL, 1),
(1875967, 256689, 42984, '<td valign="top">Great snake capture, proabably not strong enough on camouflage</td>', 'Great snake capture, proabably not strong enough on camouflage', '2005-11-17 02:10:52.000000', NULL, 1),
(1875969, 256172, 42984, '<td valign="top">Well done, clever use of colouration to get the blend</td>', 'Well done, clever use of colouration to get the blend', '2005-11-17 02:12:20.000000', NULL, 1),
(1875970, 257698, 42984, '<td valign="top">Cleverly done, not strong but meets the challenge</td>', 'Cleverly done, not strong but meets the challenge', '2005-11-17 02:14:34.000000', NULL, 1),
(1875972, 258255, 42984, '<td valign="top">Great!  Has the wow factor and meest the challenge. I never thought I''d be giving yet another cat shota ribbon score</td>', 'Great!  Has the wow factor and meest the challenge. I never thought I''d be giving yet another cat shota ribbon score', '2005-11-17 02:15:49.000000', NULL, 1),
(1875973, 257841, 45857, '<td valign="top">Interesting approach, challenge the viewer. Beautiful photo, either way.</td>', 'Interesting approach, challenge the viewer. Beautiful photo, either way.', '2005-11-17 02:16:15.000000', NULL, 1),
(1875974, 258121, 42984, '<td valign="top">Excellent capture, not strong on camouflage though</td>', 'Excellent capture, not strong on camouflage though', '2005-11-17 02:17:00.000000', NULL, 1),
(1875976, 257534, 42984, '<td valign="top">Good camo. Is that a lens flare bottom left?</td>', 'Good camo. Is that a lens flare bottom left?', '2005-11-17 02:18:54.000000', NULL, 1),
(1875979, 257663, 42984, '<td valign="top">Well done</td>', 'Well done', '2005-11-17 02:20:29.000000', NULL, 1),
(1875983, 255746, 42984, '<td valign="top">Now that''s well done</td>', 'Now that''s well done', '2005-11-17 02:21:16.000000', NULL, 1),
(1875987, 256303, 42984, '<td valign="top">Nice bug shot, possibly not enough camo for this challenge</td>', 'Nice bug shot, possibly not enough camo for this challenge', '2005-11-17 02:22:25.000000', NULL, 1),
(1875990, 258104, 42984, '<td valign="top">Not at all camo and not in focus</td>', 'Not at all camo and not in focus', '2005-11-17 02:23:36.000000', NULL, 1),
(1875991, 256083, 45857, '<td valign="top">Good subject, but just not the best presentation. For me the image speaks more of hiding in the shadows than of camouflage.</td>', 'Good subject, but just not the best presentation. For me the image speaks more of hiding in the shadows than of camouflage.', '2005-11-17 02:25:25.000000', NULL, 1),
(1875992, 258009, 42984, '<td valign="top">Good camo I think the rest of the shot is just a little dull, maybe some stong contrast would give it some wow factor</td>', 'Good camo I think the rest of the shot is just a little dull, maybe some stong contrast would give it some wow factor', '2005-11-17 02:26:04.000000', NULL, 1),
(1875994, 258063, 42984, '<td valign="top">What a pity you couldn''t get your DOF to include the foreground</td>', 'What a pity you couldn''t get your DOF to include the foreground', '2005-11-17 02:27:26.000000', NULL, 1),
(1875999, 258174, 45857, '<td valign="top">While I can see the similarities, what i don''t understand is which is masquerading as the other.</td>', 'While I can see the similarities, what i don''t understand is which is masquerading as the other.', '2005-11-17 02:28:42.000000', NULL, 1),
(1876018, 257674, 45857, '<td valign="top">A very good shot with a poetic title, but unless I''m missing something in the image, I don''t see how this shows camouflage</td>', 'A very good shot with a poetic title, but unless I''m missing something in the image, I don''t see how this shows camouflage', '2005-11-17 02:44:04.000000', NULL, 1),
(1876023, 256819, 45961, '<td valign="top">This is an amazing picture. You have shown a true natural camouflage. Is it really a spider? Or is it a beetle? I gave an 8.<br/>Good focus/clarity and lighting.</td>', 'This is an amazing picture. You have shown a true natural camouflage. Is it really a spider? Or is it a beetle? I gave an 8.Good focus/clarity and lighting.', '2005-11-17 02:46:50.000000', NULL, 1),
(1876024, 258231, 45961, '<td valign="top">When viewed in small pixels, the model truly blends in with the whole portrait. Fantastic shot. I see cracks in the paint, perhaps try another type of paint, like poster or acrylic for a better effect. I''d say oil, but the model might not like it on the facial area. I gave a 7</td>', 'When viewed in small pixels, the model truly blends in with the whole portrait. Fantastic shot. I see cracks in the paint, perhaps try another type of paint, like poster or acrylic for a better effect. I''d say oil, but the model might not like it on the facial area. I gave a 7', '2005-11-17 02:47:11.000000', NULL, 1),
(1876025, 257959, 45961, '<td valign="top">The colour and shape of the spider works very well for its camouflage. Great lighting work as well. The background works very well to bring attention to the spider and its life time plant partner. I gave you an 8 for it.</td>', 'The colour and shape of the spider works very well for its camouflage. Great lighting work as well. The background works very well to bring attention to the spider and its life time plant partner. I gave you an 8 for it.', '2005-11-17 02:47:36.000000', NULL, 1),
(1876029, 258027, 45961, '<td valign="top">I gave this a 1 not because the picture isn''t good. It''s just because I''m not sure how it fits the camouflage theme. If placed in another theme, I''d reckon I''d rate it at least a 4. A bit of clarity is missing.<br/>I''m not sure what the coloured shot would look like, but it would definitely be interesting to see.</td>', 'I gave this a 1 not because the picture isn''t good. It''s just because I''m not sure how it fits the camouflage theme. If placed in another theme, I''d reckon I''d rate it at least a 4. A bit of clarity is missing.I''m not sure what the coloured shot would look like, but it would definitely be interesting to see.', '2005-11-17 02:50:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1876033, 257593, 45857, '<td valign="top">A strong photo</td>', 'A strong photo', '2005-11-17 02:52:19.000000', NULL, 1),
(1876034, 258014, 45961, '<td valign="top">If the hands weren''t present, I''d give you a 5 because it scares the living hell out of me. It''s a first good impression, but the photo lacked something and I''m not totally feeling it. Sorry I gave a 2 on it though. The eye expression could have been filled with a bit more emphasis on the emotion.</td>', 'If the hands weren''t present, I''d give you a 5 because it scares the living hell out of me. It''s a first good impression, but the photo lacked something and I''m not totally feeling it. Sorry I gave a 2 on it though. The eye expression could have been filled with a bit more emphasis on the emotion.', '2005-11-17 02:52:25.000000', NULL, 1),
(1876040, 257168, 24983, '<td valign="top">excellent work  10</td>', 'excellent work  10', '2005-11-17 02:54:48.000000', NULL, 1),
(1876041, 256888, 45961, '<td valign="top">Sorry I gave you a 2 on this one. I just don''t see the camouflage. It''s either that good or it''s a lot of trees. If there really was something/someone lurking behind the trees, I''d instantly change your photo rating to a 7. The only thing, I think is lacking from this shot besides the camouflage is clarity. I think it''s a bit out of focus.</td>', 'Sorry I gave you a 2 on this one. I just don''t see the camouflage. It''s either that good or it''s a lot of trees. If there really was something/someone lurking behind the trees, I''d instantly change your photo rating to a 7. The only thing, I think is lacking from this shot besides the camouflage is clarity. I think it''s a bit out of focus.', '2005-11-17 02:54:50.000000', NULL, 1),
(1876045, 258085, 45961, '<td valign="top">I gave a 3 on this one because the word "love" stood out like a sore thumb. I''d give you a 5 or above if you had the word "love" uncapitalised. It''s a good shot and I like the glitter pen.</td>', 'I gave a 3 on this one because the word "love" stood out like a sore thumb. I''d give you a 5 or above if you had the word "love" uncapitalised. It''s a good shot and I like the glitter pen.', '2005-11-17 02:56:10.000000', NULL, 1),
(1876049, 257726, 45961, '<td valign="top">If I could give you a a score for your title, I''d give you a 10 out of 10. I gave a three for the effort put in. Innovative. The model should have been put into a large background to serve more as a camouflage. It might have turned out better.</td>', 'If I could give you a a score for your title, I''d give you a 10 out of 10. I gave a three for the effort put in. Innovative. The model should have been put into a large background to serve more as a camouflage. It might have turned out better.', '2005-11-17 02:57:50.000000', NULL, 1),
(1876053, 258111, 45961, '<td valign="top">This looks more like a shot for a texture or single light source challenge. I can also leave it to my imagination and prentend that you were hiding somewhere. It''s a good photo but lost it all (in my opinion) not being in the right challenge. The picture is a bit pixelated as well, so maybe a smaller photo would have done better. I hope it helps.</td>', 'This looks more like a shot for a texture or single light source challenge. I can also leave it to my imagination and prentend that you were hiding somewhere. It''s a good photo but lost it all (in my opinion) not being in the right challenge. The picture is a bit pixelated as well, so maybe a smaller photo would have done better. I hope it helps.', '2005-11-17 03:00:14.000000', NULL, 1),
(1876054, 258123, 45857, '<td valign="top">Clear winning before the start..... lol</td>', 'Clear winning before the start..... lol', '2005-11-17 03:03:07.000000', NULL, 1),
(1876056, 257971, 45961, '<td valign="top">I''d judge you for the title, but I take the challenge in a more literal way. It''s a great shot none the less. I just ended up giving a 1 on this one because it does fit (to me) into the challenge. I know you made it stuck out like a sore thumb on purpose and it''s a great effect to desaturate colours. If placed in another challenge I''d definitely give you somewhere around a 5 to 8. Sorry I gave you a 1 though.</td>', 'I''d judge you for the title, but I take the challenge in a more literal way. It''s a great shot none the less. I just ended up giving a 1 on this one because it does fit (to me) into the challenge. I know you made it stuck out like a sore thumb on purpose and it''s a great effect to desaturate colours. If placed in another challenge I''d definitely give you somewhere around a 5 to 8. Sorry I gave you a 1 though.', '2005-11-17 03:03:33.000000', NULL, 1),
(1876060, 258031, 45857, '<td valign="top">Imitation is the sincerest flattery, but I''m not sure where camouflage works here.<br/>What''s being hidden?</td>', 'Imitation is the sincerest flattery, but I''m not sure where camouflage works here.What''s being hidden?', '2005-11-17 03:05:46.000000', NULL, 1),
(1876062, 258179, 45961, '<td valign="top">I thought this was rather witty of you to place the lens into a scotch bottle container and then placing it on a leather jacket. A good disguise for the lens. I gave a 4 though because it didn''t give a good first impression.</td>', 'I thought this was rather witty of you to place the lens into a scotch bottle container and then placing it on a leather jacket. A good disguise for the lens. I gave a 4 though because it didn''t give a good first impression.', '2005-11-17 03:06:12.000000', NULL, 1),
(1876063, 257657, 42984, '<td valign="top">Can''t really properly vote on this due to severe out of focus</td>', 'Can''t really properly vote on this due to severe out of focus', '2005-11-17 03:06:25.000000', NULL, 1),
(1876065, 257583, 45961, '<td valign="top">I gave you a 4 because of the creavity and effort you put into this shot. I think you''re missing a book though. I would have thought from this angle you''d be able to see at least the corner of the book. I''d give it a 6, but because this picture was lacking that book and it''s grainy.</td>', 'I gave you a 4 because of the creavity and effort you put into this shot. I think you''re missing a book though. I would have thought from this angle you''d be able to see at least the corner of the book. I''d give it a 6, but because this picture was lacking that book and it''s grainy.', '2005-11-17 03:08:10.000000', NULL, 1),
(1876067, 257179, 42984, '<td valign="top">Very very interesting.  It looks dull and in need of some ''glow'' to add to the wow fctor, but is cool image.</td>', 'Very very interesting.  It looks dull and in need of some ''glow'' to add to the wow fctor, but is cool image.', '2005-11-17 03:08:29.000000', NULL, 1),
(1876068, 257733, 42984, '<td valign="top">Lot of work, well lanned and executed</td>', 'Lot of work, well lanned and executed', '2005-11-17 03:09:56.000000', NULL, 1),
(1876070, 258095, 45961, '<td valign="top">This is very much like the shot that won second place on a challenge done not so long ago. Very well set up, but I think it needs a bit more originality. So I gave this a 4. It''s aligned almost perfectly, but a few gliches. Sorry I gave this a 4, I believe it deserves more like a 7 at least. Like I just said, the effect was recently done so I took off a lot of points there.</td>', 'This is very much like the shot that won second place on a challenge done not so long ago. Very well set up, but I think it needs a bit more originality. So I gave this a 4. It''s aligned almost perfectly, but a few gliches. Sorry I gave this a 4, I believe it deserves more like a 7 at least. Like I just said, the effect was recently done so I took off a lot of points there.', '2005-11-17 03:11:01.000000', NULL, 1),
(1876073, 257663, 17507, '<td valign="top">great example of camouflage, but the composition is quite cluttered, substantially detracting from the focus of the picture.</td>', 'great example of camouflage, but the composition is quite cluttered, substantially detracting from the focus of the picture.', '2005-11-17 03:14:42.000000', NULL, 1),
(1876081, 257814, 17507, '<td valign="top">nice greens and color complement - but this is concealment, not camouflage - while any kind of concealment could be construed as a kind of camouflage, this is simply not a strong enough example of it for me to feel that this meets the challenge well.</td>', 'nice greens and color complement - but this is concealment, not camouflage - while any kind of concealment could be construed as a kind of camouflage, this is simply not a strong enough example of it for me to feel that this meets the challenge well.', '2005-11-17 03:17:47.000000', NULL, 1),
(1876086, 257608, 17507, '<td valign="top">The link to the challenge is too loose for me.</td>', 'The link to the challenge is too loose for me.', '2005-11-17 03:19:38.000000', NULL, 1),
(1876093, 258234, 17507, '<td valign="top">gorgeous contours, but I wish that the composition were a bit less abstract! I think this would have met the challenge with no less finesse if you had shown more (or the whole) of the model</td>', 'gorgeous contours, but I wish that the composition were a bit less abstract! I think this would have met the challenge with no less finesse if you had shown more (or the whole) of the model', '2005-11-17 03:23:06.000000', NULL, 1),
(1876096, 257319, 17507, '<td valign="top">I''m afraid I see no link to the challenge here.</td>', 'I''m afraid I see no link to the challenge here.', '2005-11-17 03:24:20.000000', NULL, 1),
(1876098, 256886, 17507, '<td valign="top">I''m afraid I don''t see this as camouflage.</td>', 'I''m afraid I don''t see this as camouflage.', '2005-11-17 03:24:42.000000', NULL, 1),
(1876099, 258083, 17507, '<td valign="top">very cute :)</td>', 'very cute :)', '2005-11-17 03:25:01.000000', NULL, 1),
(1876101, 256738, 17507, '<td valign="top">wow, that wing is the spitting image of a decaying leaf. great choice of subject for this challenge.</td>', 'wow, that wing is the spitting image of a decaying leaf. great choice of subject for this challenge.', '2005-11-17 03:26:39.000000', NULL, 1),
(1876104, 256781, 42984, '<td valign="top">Pretty clever and well photographed</td>', 'Pretty clever and well photographed', '2005-11-17 03:27:14.000000', NULL, 1),
(1876142, 258230, 42984, '<td valign="top">Interesting scene.  Youve maybe left too much of the foreground to get the best of what you have here. You certainly needed to loose the car spoiler and I''m not sure if loosing the sign would throw the focus out into the hills area for more impact.</td>', 'Interesting scene.  Youve maybe left too much of the foreground to get the best of what you have here. You certainly needed to loose the car spoiler and I''m not sure if loosing the sign would throw the focus out into the hills area for more impact.', '2005-11-17 03:51:44.000000', NULL, 1),
(1876145, 257951, 42984, '<td valign="top">What a fab shot.  Am not sure that is very camouflaged though</td>', 'What a fab shot.  Am not sure that is very camouflaged though', '2005-11-17 03:53:15.000000', NULL, 1),
(1876147, 258026, 42984, '<td valign="top">What an interesting shot.  The slow shutter motion is great yet you''ve managed to get the dog sharper than I though you would.  Camo is a bit dubious but otherwise great.</td>', 'What an interesting shot.  The slow shutter motion is great yet you''ve managed to get the dog sharper than I though you would.  Camo is a bit dubious but otherwise great.', '2005-11-17 03:55:19.000000', NULL, 1),
(1876153, 257582, 42984, '<td valign="top">Nice colour match.  I think you could have done a lot with this if you''d sent some more time with it. The grass is distracting and not realy necessary as it lessens the impact of the image.</td>', 'Nice colour match.  I think you could have done a lot with this if you''d sent some more time with it. The grass is distracting and not realy necessary as it lessens the impact of the image.', '2005-11-17 04:05:02.000000', NULL, 1),
(1876160, 257993, 42984, '<td valign="top">Too messy and without a point of interest.  It just makes it difficult for viewers to relate to your image</td>', 'Too messy and without a point of interest.  It just makes it difficult for viewers to relate to your image', '2005-11-17 04:32:31.000000', NULL, 1),
(1876162, 257676, 42984, '<td valign="top">Very powerful, very disturbing = great.</td>', 'Very powerful, very disturbing = great.', '2005-11-17 04:35:35.000000', NULL, 1),
(1876174, 258213, 18552, '<td valign="top">How cute - this little alligator looks like it''s smiling for a picture! Very nice photo quality and suits the challenge very well.</td>', 'How cute - this little alligator looks like it''s smiling for a picture! Very nice photo quality and suits the challenge very well.', '2005-11-17 04:58:26.000000', NULL, 1),
(1876178, 257951, 18552, '<td valign="top">Very nice owl capture.</td>', 'Very nice owl capture.', '2005-11-17 04:59:05.000000', NULL, 1),
(1876180, 256311, 18552, '<td valign="top">This is beautiful - so delicate and charming. Great job!</td>', 'This is beautiful - so delicate and charming. Great job!', '2005-11-17 04:59:48.000000', NULL, 1),
(1876184, 257211, 18552, '<td valign="top">This cat really does blend into the background. The flash glare really takes away from the picture though. If you could have found a way to take this without the flash it would have been more visually appealling. Also, the sharpening might be a bit strong as the whiskers have little jaggies.</td>', 'This cat really does blend into the background. The flash glare really takes away from the picture though. If you could have found a way to take this without the flash it would have been more visually appealling. Also, the sharpening might be a bit strong as the whiskers have little jaggies.', '2005-11-17 05:02:16.000000', NULL, 1),
(1876186, 255907, 18552, '<td valign="top">This is great. Just right for the challenge and very well taken, too.</td>', 'This is great. Just right for the challenge and very well taken, too.', '2005-11-17 05:04:48.000000', NULL, 1),
(1876187, 256845, 18552, '<td valign="top">Lovely capture for a low light situation. Perfect for the challenge!</td>', 'Lovely capture for a low light situation. Perfect for the challenge!', '2005-11-17 05:05:24.000000', NULL, 1),
(1876189, 258158, 18552, '<td valign="top">What a nice picture! The colors are beautiful, the snake really blends in to these leaves. Perfect for the challenge and well taken, too.</td>', 'What a nice picture! The colors are beautiful, the snake really blends in to these leaves. Perfect for the challenge and well taken, too.', '2005-11-17 05:07:24.000000', NULL, 1),
(1876194, 256819, 18552, '<td valign="top">Wow, this is perfect for the challenge! This spider totally blends into the background. Very well done photo.</td>', 'Wow, this is perfect for the challenge! This spider totally blends into the background. Very well done photo.', '2005-11-17 05:09:39.000000', NULL, 1),
(1876195, 256083, 18552, '<td valign="top">This suits the challenge perfectly. However, the photo quality itself isn''t that good. Nothing in the picture is actually in focus.</td>', 'This suits the challenge perfectly. However, the photo quality itself isn''t that good. Nothing in the picture is actually in focus.', '2005-11-17 05:10:44.000000', NULL, 1),
(1876198, 257349, 18552, '<td valign="top">This is just lovely! Such soft inviting colors and perfect colors and compostion. My pick for a ribbon.</td>', 'This is just lovely! Such soft inviting colors and perfect colors and compostion. My pick for a ribbon.', '2005-11-17 05:12:15.000000', NULL, 1),
(1876200, 256728, 18552, '<td valign="top">Perfect for the challenge. The blown out highlights really detract from this photo. Since the alligator is the subject of the picture it would be nice to have a good sharp focus on that. The whole picture is slightly out of focus.</td>', 'Perfect for the challenge. The blown out highlights really detract from this photo. Since the alligator is the subject of the picture it would be nice to have a good sharp focus on that. The whole picture is slightly out of focus.', '2005-11-17 05:16:47.000000', NULL, 1),
