(1876203, 257658, 18552, '<td valign="top">Fits the challenge perfectly. I think a tighter crop on the bottom would make this a stronger picture.</td>', 'Fits the challenge perfectly. I think a tighter crop on the bottom would make this a stronger picture.', '2005-11-17 05:19:06.000000', NULL, 1),
(1876205, 256172, 18552, '<td valign="top">Fits the challenge very well! I think if you cropped this a bit differently so the duck was on one of the thirds on the left it would have been a much stronger composition. Also, the focus on the duck itself could be a bit sharper.</td>', 'Fits the challenge very well! I think if you cropped this a bit differently so the duck was on one of the thirds on the left it would have been a much stronger composition. Also, the focus on the duck itself could be a bit sharper.', '2005-11-17 05:21:26.000000', NULL, 1),
(1876206, 257663, 18552, '<td valign="top">Suits the challenge perfectly! The picture quality itself is great, too. However, the crop is off - you have that white band on the right side and I think more could get cropped off  bottom as well to give this a stronger composition.</td>', 'Suits the challenge perfectly! The picture quality itself is great, too. However, the crop is off - you have that white band on the right side and I think more could get cropped off  bottom as well to give this a stronger composition.', '2005-11-17 05:22:47.000000', NULL, 1),
(1876208, 255878, 18552, '<td valign="top">Wow - great picture. So well done &amp; suits the challenge perfectly.</td>', 'Wow - great picture. So well done & suits the challenge perfectly.', '2005-11-17 05:24:31.000000', NULL, 1),
