(1877021, 256254, 45790, '<td valign="top">Unfortunately spoiled by poor focus.</td>', 'Unfortunately spoiled by poor focus.', '2005-11-17 12:54:25.000000', NULL, 1),
(1877023, 257211, 45790, '<td valign="top">Clever idea. A little bit overexposed, but works well.</td>', 'Clever idea. A little bit overexposed, but works well.', '2005-11-17 12:55:42.000000', NULL, 1),
(1877025, 256348, 45790, '<td valign="top">Cute, but not camouflaged. Technically a good job.</td>', 'Cute, but not camouflaged. Technically a good job.', '2005-11-17 12:56:48.000000', NULL, 1),
(1877027, 258109, 45790, '<td valign="top">The garbage challenge was *last* week. In any case, framing with the trash pretty much dead center gives it away.</td>', 'The garbage challenge was *last* week. In any case, framing with the trash pretty much dead center gives it away.', '2005-11-17 12:59:17.000000', NULL, 1),
(1877028, 256843, 45790, '<td valign="top">Well done. Can''t find a flaw.</td>', 'Well done. Can''t find a flaw.', '2005-11-17 13:00:02.000000', NULL, 1),
(1877032, 257658, 45790, '<td valign="top">I don''t really think it''s hidden. In any case it is fairly well centered on the frame which makes it stand out, not be camouflaged.</td>', 'I don''t really think it''s hidden. In any case it is fairly well centered on the frame which makes it stand out, not be camouflaged.', '2005-11-17 13:02:57.000000', NULL, 1),
(1877039, 258160, 45790, '<td valign="top">Now if the fitting were the same color as the screws, then it would be camouflaged. But as it is it really stands out. But I do like the shot, just not for the topic.</td>', 'Now if the fitting were the same color as the screws, then it would be camouflaged. But as it is it really stands out. But I do like the shot, just not for the topic.', '2005-11-17 13:05:42.000000', NULL, 1),
(1877042, 255907, 39825, '<td valign="top">Hot. ;-)</td>', 'Hot. ;-)', '2005-11-17 13:06:56.000000', NULL, 1),
(1877045, 258169, 45790, '<td valign="top">A real stretch. Would be better if the cat were hiding, or at least not perfectly centered and well lit in the frame. Would have also helped if you didn''t use a flash here.</td>', 'A real stretch. Would be better if the cat were hiding, or at least not perfectly centered and well lit in the frame. Would have also helped if you didn''t use a flash here.', '2005-11-17 13:08:37.000000', NULL, 1),
(1877047, 256172, 45790, '<td valign="top">I like this. But would have liked it more if the subject being camouflaged wasn''t in the center of the frame.</td>', 'I like this. But would have liked it more if the subject being camouflaged wasn''t in the center of the frame.', '2005-11-17 13:09:51.000000', NULL, 1),
(1877056, 257859, 45790, '<td valign="top">Now if the car were white then this would have been the the equivalent of the vanilla ice cream in the snow storm. But somehow I have no problem spotting the car.</td>', 'Now if the car were white then this would have been the the equivalent of the vanilla ice cream in the snow storm. But somehow I have no problem spotting the car.', '2005-11-17 13:14:13.000000', NULL, 1),
(1877076, 257733, 8367, '<td valign="top">Too Funny! Not sure how you (or your model) managed to keep a straight face. ha ha ha</td>', 'Too Funny! Not sure how you (or your model) managed to keep a straight face. ha ha ha', '2005-11-17 13:22:25.000000', NULL, 1),
(1877087, 256691, 43714, '<td valign="top">This is very sweet, great shot. It''s hard too capture birds.</td>', 'This is very sweet, great shot. It''s hard too capture birds.', '2005-11-17 13:27:05.000000', NULL, 1),
(1877091, 257959, 43714, '<td valign="top">Great shot, focus, and colour. He''s a hairy little fellow.</td>', 'Great shot, focus, and colour. He''s a hairy little fellow.', '2005-11-17 13:28:17.000000', NULL, 1),
(1877096, 258198, 43714, '<td valign="top">Good subject, but its a little out of focus for me, maybe a closer shot would have showed the subject better.</td>', 'Good subject, but its a little out of focus for me, maybe a closer shot would have showed the subject better.', '2005-11-17 13:30:02.000000', NULL, 1),
(1877098, 256685, 43714, '<td valign="top">Good idea, I think the picture could have been bigger.</td>', 'Good idea, I think the picture could have been bigger.', '2005-11-17 13:31:04.000000', NULL, 1),
(1877100, 258131, 45857, '<td valign="top">Clever idea and a good photo, however the paper clip is merely hiding in the staples, not trying to look like one.</td>', 'Clever idea and a good photo, however the paper clip is merely hiding in the staples, not trying to look like one.', '2005-11-17 13:32:25.000000', NULL, 1),
(1877101, 257988, 43714, '<td valign="top">Great camouflage shot but it seems a little out of focus.</td>', 'Great camouflage shot but it seems a little out of focus.', '2005-11-17 13:32:32.000000', NULL, 1),
(1877103, 257740, 43714, '<td valign="top">Good camouflage shot, I like  the B&amp;W.</td>', 'Good camouflage shot, I like  the B&W.', '2005-11-17 13:34:06.000000', NULL, 1),
(1877104, 258003, 43714, '<td valign="top">I like your subject and camouflage but the plant is distracting and its a bit out of focus.</td>', 'I like your subject and camouflage but the plant is distracting and its a bit out of focus.', '2005-11-17 13:35:19.000000', NULL, 1),
(1877107, 256422, 43714, '<td valign="top">Nice shot</td>', 'Nice shot', '2005-11-17 13:35:54.000000', NULL, 1),
(1877108, 256843, 45857, '<td valign="top">great photo, technically, however, your hiden subject is merely hiding. If I had some sense that the leaves were stuck to ''him'' or if his face was painted, then it would be camouflage.   Sorry</td>', 'great photo, technically, however, your hiden subject is merely hiding. If I had some sense that the leaves were stuck to ''him'' or if his face was painted, then it would be camouflage.   Sorry', '2005-11-17 13:36:03.000000', NULL, 1),
(1877110, 256689, 43714, '<td valign="top">I like the subject focused and the blurry background, great job.</td>', 'I like the subject focused and the blurry background, great job.', '2005-11-17 13:37:29.000000', NULL, 1),
(1877111, 256728, 45857, '<td valign="top">Always thought of ''gators'' in terms of hiding or lurking, but green on green works.</td>', 'Always thought of ''gators'' in terms of hiding or lurking, but green on green works.', '2005-11-17 13:37:58.000000', NULL, 1),
(1877119, 258262, 16106, '<td valign="top">nice delicacy,but just too dimly lit.</td>', 'nice delicacy,but just too dimly lit.', '2005-11-17 13:40:08.000000', NULL, 1),
