(1877121, 255878, 43714, '<td valign="top">Great shot, nice colour, I love your subjects!</td>', 'Great shot, nice colour, I love your subjects!', '2005-11-17 13:40:19.000000', NULL, 1),
(1877127, 257853, 16106, '<td valign="top">beautifull shot that would have done better in free study than this challenge, where I have trouble seeing what is being camoflaged.</td>', 'beautifull shot that would have done better in free study than this challenge, where I have trouble seeing what is being camoflaged.', '2005-11-17 13:41:42.000000', NULL, 1),
