(1883331, 257733, 40019, '<td valign="top">Very imaginative!  Good one.</td>', 'Very imaginative!  Good one.', '2005-11-19 18:18:26.000000', NULL, 1),
(1883333, 258158, 33672, '<td valign="top">I love the colors and the comp. With a bit more contrast this is a ten.</td>', 'I love the colors and the comp. With a bit more contrast this is a ten.', '2005-11-19 18:19:08.000000', NULL, 1),
(1883334, 256772, 40019, '<td valign="top">Great colors!</td>', 'Great colors!', '2005-11-19 18:19:24.000000', NULL, 1),
(1883336, 257591, 33672, '<td valign="top">I started taking photos to try and catch something like this! Nice job!</td>', 'I started taking photos to try and catch something like this! Nice job!', '2005-11-19 18:19:55.000000', NULL, 1),
(1883337, 255851, 33672, '<td valign="top">Great Photo! Ccould use a levels adj and a bit more contrast.</td>', 'Great Photo! Ccould use a levels adj and a bit more contrast.', '2005-11-19 18:20:46.000000', NULL, 1),
(1883339, 258225, 40019, '<td valign="top">Nicely done, I had to take a closer look at this one to get it.  Great lighting for effect.</td>', 'Nicely done, I had to take a closer look at this one to get it.  Great lighting for effect.', '2005-11-19 18:21:17.000000', NULL, 1),
(1883340, 256217, 40019, '<td valign="top">Creative!  Although not sure if spotlighting DPC helped or hurt.  If you moved it out of the spotlight - would have been better camouflage, but people may have missed it.  Creative shot, I like it.</td>', 'Creative!  Although not sure if spotlighting DPC helped or hurt.  If you moved it out of the spotlight - would have been better camouflage, but people may have missed it.  Creative shot, I like it.', '2005-11-19 18:23:36.000000', NULL, 1),
(1883343, 257787, 40019, '<td valign="top">Very clever!  Nicely done - great lighting.  Looks like you have your Christmas card for the year done.</td>', 'Very clever!  Nicely done - great lighting.  Looks like you have your Christmas card for the year done.', '2005-11-19 18:26:16.000000', NULL, 1),
(1883346, 257628, 40019, '<td valign="top">Cute!</td>', 'Cute!', '2005-11-19 18:26:47.000000', NULL, 1),
(1883350, 257583, 40019, '<td valign="top">Ha!  Nicely done!</td>', 'Ha!  Nicely done!', '2005-11-19 18:27:57.000000', NULL, 1),
(1883351, 257959, 40019, '<td valign="top">Wow!  Nice macro!  Great find - fits the challenge perfectly!</td>', 'Wow!  Nice macro!  Great find - fits the challenge perfectly!', '2005-11-19 18:28:25.000000', NULL, 1),
(1883354, 258255, 40019, '<td valign="top">Great picture!  Great focus on the eyes, great color!  Looks like the cover to Cats.  Nicely done.</td>', 'Great picture!  Great focus on the eyes, great color!  Looks like the cover to Cats.  Nicely done.', '2005-11-19 18:29:49.000000', NULL, 1),
(1883357, 258251, 40019, '<td valign="top">Great find!  Fits the challenge perfectly.  Nicely done.</td>', 'Great find!  Fits the challenge perfectly.  Nicely done.', '2005-11-19 18:31:18.000000', NULL, 1),
(1883358, 257658, 40019, '<td valign="top">Great macro!  Fits the challenge well!</td>', 'Great macro!  Fits the challenge well!', '2005-11-19 18:31:43.000000', NULL, 1),
(1883359, 256172, 10047, '<td valign="top">I might have cropped the duck into the lower left corner to make the viewer hunt a little bit. The autofocus looks like it might have been a little soft in the low light condition.</td>', 'I might have cropped the duck into the lower left corner to make the viewer hunt a little bit. The autofocus looks like it might have been a little soft in the low light condition.', '2005-11-19 18:31:47.000000', NULL, 1),
(1883360, 257698, 40019, '<td valign="top">Nicely done!  Just enough exposure and focus to see the cat in the back.</td>', 'Nicely done!  Just enough exposure and focus to see the cat in the back.', '2005-11-19 18:32:23.000000', NULL, 1),
(1883361, 258077, 40019, '<td valign="top">Great cropping!  Nicely done.</td>', 'Great cropping!  Nicely done.', '2005-11-19 18:32:50.000000', NULL, 1),
(1883362, 257582, 40019, '<td valign="top">Cute!</td>', 'Cute!', '2005-11-19 18:33:05.000000', NULL, 1),
(1883365, 258158, 40019, '<td valign="top">Nice find!  Great rich colors!  Fits challenge perfectly!</td>', 'Nice find!  Great rich colors!  Fits challenge perfectly!', '2005-11-19 18:33:53.000000', NULL, 1),
(1883368, 257837, 10047, '<td valign="top">I think the flash highlighted the brush on the left side, and draws your eye there. I might have tried cropping so the giraffe was on the left and there was less brush.</td>', 'I think the flash highlighted the brush on the left side, and draws your eye there. I might have tried cropping so the giraffe was on the left and there was less brush.', '2005-11-19 18:34:38.000000', NULL, 1),
(1883370, 258085, 40019, '<td valign="top">I got a letter like this once.  Then I got a restraining order.  :-)  <br/>Clever, I like it!  No, I hate it!.  No, I love it!</td>', 'I got a letter like this once.  Then I got a restraining order.  :-)  Clever, I like it!  No, I hate it!.  No, I love it!', '2005-11-19 18:35:11.000000', NULL, 1),
(1883373, 256686, 40019, '<td valign="top">Nicely done!  I really had to look hard at this one!</td>', 'Nicely done!  I really had to look hard at this one!', '2005-11-19 18:35:52.000000', NULL, 1),
(1883375, 258187, 40019, '<td valign="top">Very cute. I would have saturated the colors just a little more.</td>', 'Very cute. I would have saturated the colors just a little more.', '2005-11-19 18:37:33.000000', NULL, 1),
(1883377, 257706, 10047, '<td valign="top">A little on the small side, and my eye is drawn to the backlighting in the upper right. Not sure if you could have cropped differently to avoid that.</td>', 'A little on the small side, and my eye is drawn to the backlighting in the upper right. Not sure if you could have cropped differently to avoid that.', '2005-11-19 18:37:57.000000', NULL, 1),
(1883382, 257841, 40019, '<td valign="top">Great picture!  Nicely done.  Perfect title.</td>', 'Great picture!  Nicely done.  Perfect title.', '2005-11-19 18:40:28.000000', NULL, 1),
(1883383, 257674, 10047, '<td valign="top">I like to sharpen and saturate to see if I could make the sunrays more pronounced.</td>', 'I like to sharpen and saturate to see if I could make the sunrays more pronounced.', '2005-11-19 18:40:46.000000', NULL, 1),
(1883384, 255746, 40019, '<td valign="top">Great effect!  Nicely done.</td>', 'Great effect!  Nicely done.', '2005-11-19 18:40:55.000000', NULL, 1),
(1883386, 258231, 40019, '<td valign="top">Well executed!  A little creepy too!  :-)</td>', 'Well executed!  A little creepy too!  :-)', '2005-11-19 18:41:53.000000', NULL, 1),
(1883391, 258098, 10047, '<td valign="top">Sea Biscuit is well placed in the photo, but a little soft on focus. Too bad we couldn''t spot edit and sharpen him a little.</td>', 'Sea Biscuit is well placed in the photo, but a little soft on focus. Too bad we couldn''t spot edit and sharpen him a little.', '2005-11-19 18:43:46.000000', NULL, 1),
(1883395, 256691, 10047, '<td valign="top">I think I would have cropped the sparrow over to the left. Looks like the autofocus might have grabbed the branch above his head and left him a little soft.</td>', 'I think I would have cropped the sparrow over to the left. Looks like the autofocus might have grabbed the branch above his head and left him a little soft.', '2005-11-19 18:45:55.000000', NULL, 1),
(1883496, 256254, 10047, '<td valign="top">Beautiful blue sky, but the focus is a little off. Looks like the autofocus chose the branch behind the woodpecker.</td>', 'Beautiful blue sky, but the focus is a little off. Looks like the autofocus chose the branch behind the woodpecker.', '2005-11-19 20:05:28.000000', NULL, 1),
